CREATE DATABASE roastery
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;

INSERT INTO coffees (name, origin, roast, price, stock) VALUES
  ('Morning Blend', 'Brazil', 'medium', 12.50, 40),
  ('Yirgacheffe', 'Ethiopia', 'light', 16.00, 25);

INSERT INTO coffees (id, name, origin, roast, price, stock)
VALUES (4, 'Decaf Colombia', 'Colombia', 'medium', 13.75, 8) AS new
ON DUPLICATE KEY UPDATE stock = coffees.stock + new.stock;

INSERT INTO customers (name, email, city, joined_on)
VALUES ('Noor Haddad', 'noor@example.com', 'Amman', '2026-11-01');
SELECT LAST_INSERT_ID();

SELECT o.id, c.name
FROM orders o
JOIN customers c ON c.id = o.customer_id;

SELECT CONCAT(name, ' (', city, ')') AS customer,
       DATE_FORMAT(joined_on, '%b %Y') AS since
FROM customers;

SELECT INDEX_NAME, COLUMN_NAME, NON_UNIQUE
FROM information_schema.STATISTICS
WHERE TABLE_SCHEMA = 'roastery' AND TABLE_NAME = 'orders';

CREATE ROLE 'app_rw';
GRANT SELECT, INSERT, UPDATE, DELETE ON roastery.* TO 'app_rw';
GRANT 'app_rw' TO 'api'@'%';
SET DEFAULT ROLE ALL TO 'api'@'%';

START TRANSACTION;
UPDATE coffees SET stock = stock - 2 WHERE id = 1;
INSERT INTO orders (customer_id, coffee_id, quantity, status) VALUES (5, 1, 2, 'paid');
COMMIT;

START TRANSACTION;
UPDATE coffees SET price = 99 WHERE id = 1;
SAVEPOINT before_stock;
UPDATE coffees SET stock = 0 WHERE id = 1;
ROLLBACK TO before_stock;
ROLLBACK;
